#!/usr/bin/env python3
"""Nagrik Saathi static build: content/*.json -> dist/ (no dependencies)."""
import json,glob,os,shutil,html
SITE=(os.environ.get('SITE_URL') or 'https://nagriksaathi.in').rstrip('/')
E=html.escape
import datetime as _dt
NOW=os.environ.get('BUILD_DATE') or _dt.date.today().isoformat()  # build date: expiry and staleness are checked against this
REVIEW_DAYS=180   # a record not re-verified for this many days shows a "re-check due" note
UPDATE_DAYS=180   # a What's-new entry without its own 'expires' disappears after this many days
MH=['जनवरी','फ़रवरी','मार्च','अप्रैल','मई','जून','जुलाई','अगस्त','सितंबर','अक्टूबर','नवंबर','दिसंबर'];ME=['January','February','March','April','May','June','July','August','September','October','November','December']
def D(d): return _dt.date.fromisoformat(d)
def fd(d): x=D(d);return sp(f'{x.day} {MH[x.month-1]} {x.year}',f'{x.day} {ME[x.month-1]} {x.year}')
def live(r): return not r.get('valid_until') or r['valid_until']>=NOW
def _all():
    for f in glob.glob('content/*/*.json'):
        r=json.load(open(f,encoding='utf-8'))
        if r.get('status')=='verified' and live(r): yield r
UPD=[u for u in json.load(open('content/updates.json',encoding='utf-8')) if (u.get('expires') or (D(u['date'])+_dt.timedelta(days=UPDATE_DAYS)).isoformat())>=NOW]
UPD.sort(key=lambda u:u['date'],reverse=True)
SITE_UPDATED=max([r.get('updated') or r.get('last_verified') or '2026-01-01' for r in _all()]+[u['date'] for u in UPD]+[json.load(open('content/meta.json'))['site_updated'] if os.path.exists('content/meta.json') else '2026-01-01'])
TODAY=SITE_UPDATED
EXPIRED=[];REVIEW_DUE=[]
def sp(h,e): return f'<span lang="hi">{h}</span><span lang="en">{e}</span>'
def t(h,e,tag='p',c=''):
    c=f' class="{c}"' if c else '';return f'<{tag}{c} lang="hi">{h}</{tag}><{tag}{c} lang="en">{e}</{tag}>'
def sec(h,e,b): return t(h,e,'h2')+b
def ul(h,e): return ''.join(f'<ul lang="{l}">'+''.join(f'<li>{E(x)}</li>' for x in a)+'</ul>' for l,a in(('hi',h),('en',e)))
ST={"verified":("🟢","आधिकारिक स्रोत से सत्यापित","Verified from official source"),"pending":("🟡","आधिकारिक अपडेट मिला — सत्यापन बाकी","Official update detected — verification pending"),"unverified":("🔴","वर्तमान जानकारी सत्यापित नहीं हो सकी","Current information could not be verified")}
def badge(s): i,h,e=ST[s];return f'<span class="badge s-{s}">{i} {sp(h,e)}</span>'
def bext(u,l): return f'<a href="{E(u)}" target="_blank" rel="noopener" data-biz="1">{l}</a> <small>↗ {sp("बाहरी वेबसाइट खुलेगी","Opens external website")}</small>'  # promoted business links: NO noreferrer, official URL exactly as published, no tracking params
def ext(u,l): return f'<a href="{E(u)}" target="_blank" rel="noopener noreferrer">{l}</a> <small>↗ {sp("आधिकारिक बाहरी वेबसाइट खुलेगी","Opens official external website")}</small>'
KIND={"schemes":("योजनाएँ","Schemes"),"documents":("दस्तावेज़ और प्रमाणपत्र","Documents & certificates"),"scams":("स्कैम से सुरक्षा","Scam safety")}
NAV=[("/","होम","Home"),("/schemes/","योजनाएँ","Schemes"),("/services/","सेवाएँ","Services"),("/housing/","घर","Housing"),("/livelihood/","रोज़गार / MSME","Jobs & MSME"),("/finder/","मेरे लिए क्या?","For me"),("/central/","केंद्र","Central"),("/states/","राज्य","States"),("/documents/","दस्तावेज़","Documents"),("/cyber-safety/","साइबर सुरक्षा","Cyber Safety"),("/scams/","ठगी से बचाव","Scam Safety"),("/helplines/","हेल्पलाइन","Helplines"),("/whats-new/","क्या नया?","What's New"),("/audio/","ऑडियो","Audio"),("/how-it-works/","कैसे काम करता है","How it works"),("/about/","परिचय","About")]
DISC=t("नागरिक साथी एक स्वतंत्र नागरिक-सूचना मंच है। यह कोई सरकारी वेबसाइट, विभाग या सरकारी साझेदार नहीं है। जानकारी सामान्य जागरूकता के लिए है; कदम उठाने से पहले आधिकारिक स्रोत जाँचें। अंतिम निर्णय संबंधित प्राधिकरण का होता है।","Nagrik Saathi is an independent citizen-information platform. It is not a government website, department or partner. Information is for general awareness; check official sources before acting. Final decisions rest with the relevant authority.")
PAGES=[];OUT={};LASTMOD={}
def layout(path,th,te,body,desc,crumbs=None,noindex=False,listen=True):
    url=SITE+path;nav=''.join(f'<a href="{p}"{" aria-current=page" if p==path else ""}>{sp(h,e)}</a>' for p,h,e in NAV)
    ld=''
    if crumbs:
        ld='<script type="application/ld+json">'+json.dumps({"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":i+1,"name":n,"item":SITE+u} for i,(n,u) in enumerate([("Home","/")]+crumbs+[(te,path)])]},ensure_ascii=False)+'</script>'
    bc=''.join(f' › <a href="{u}">{n}</a>' for n,u in crumbs or [])
    crumb=f'<nav aria-label="Breadcrumb" class="w m" style="background:none;border:0"><a href="/">Home</a>{bc} › {E(te)}</nav>' if crumbs else ''
    ls='<p><button class="listen" type="button">🔊 '+sp("सुनें","Listen")+'</button> <small id="lm" aria-live="polite"></small></p>' if listen else ''
    ti=f'{th} — {te} | Nagrik Saathi' if path!='/' else 'नागरिक साथी — Nagrik Saathi | Government information, simple and clear'
    OUT[path]=f'''<!DOCTYPE html><html lang="hi" data-lang="hi"><head><meta charset="utf-8"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{E(ti)}</title><meta name="description" content="{E(desc)}">{'<meta name="robots" content="noindex">' if noindex else ''}<link rel="canonical" href="{url}"><meta property="og:title" content="{E(ti)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><link rel="stylesheet" href="/assets/site.css"><link rel="icon" type="image/png" sizes="32x32" href="/assets/img/favicon-32.png"><link rel="apple-touch-icon" href="/assets/img/apple-touch-icon.png"><meta property="og:image" content="{SITE}/assets/img/og-banner.jpg"><meta property="og:image:width" content="1024"><meta property="og:image:height" content="572"><meta property="og:image:alt" content="नागरिक साथी — सरकारी योजनाएँ और नागरिक सेवाएँ, सबके लिए आसान"><meta name="twitter:card" content="summary_large_image"><meta property="og:site_name" content="Nagrik Saathi">{ld}<script src="/assets/app.js" defer></script></head><body>
<header><div class="w"><a class="logo" href="/"><img src="/assets/img/logo-mark.png" width="40" height="40" alt="" class="lm">नागरिक साथी · Nagrik Saathi</a><div><button id="bk" type="button">← {sp("पीछे","Back")}</button> <button data-l="hi" type="button" aria-pressed="true">हिंदी</button> <button data-l="en" type="button" aria-pressed="false">English</button> <button id="sn" type="button" aria-pressed="false">👴 {sp("सीनियर मोड","Senior mode")}</button></div></div></header>
<nav aria-label="Main"><div class="w">{nav}</div></nav>{crumb}<main class="w">{ls}{body}</main>
<footer><div class="w">{DISC}<p><a href="/privacy/">{sp("गोपनीयता","Privacy")}</a><a href="/terms/">{sp("शर्तें","Terms")}</a><a href="/disclaimer/">{sp("अस्वीकरण","Disclaimer")}</a><a href="/accessibility/">{sp("सुगम्यता","Accessibility")}</a><a href="/report/">{sp("गलती बताएँ","Report an Error")}</a><a href="/search/">{sp("खोज","Search")}</a></p><p class="m">{sp("साइट का अंतिम अपडेट","Site last updated")}: {fd(SITE_UPDATED)} · <a href="/whats-new/">{sp("क्या नया है?","What's new?")}</a></p></div></footer></body></html>'''
    if not noindex: PAGES.append((path,LASTMOD.pop(path,SITE_UPDATED)))
def page(path,th,te,body,desc,**k): layout(path,th,te,t(th,te,'h1')+body,desc,**k)
def load(k):
    out=[]
    for f in sorted(glob.glob(f'content/{k}/*.json')):
        r=json.load(open(f,encoding='utf-8'))
        if r.get('status')!='verified': continue   # only fully verified records are published
        if not live(r): EXPIRED.append(f);continue  # past its valid_until date: hidden automatically
        out.append(r)
    return out  # only fully verified records are published
def rec(k,r):
    kh,ke=KIND[k];w=lambda x:t(E(r[x+'_hi']),E(r[x+'_en']))
    if k=='scams': b=sec('यह कैसे काम करता है','How it works',w('how'))+sec('चेतावनी के संकेत','Warning signs',ul(r['signs_hi'],r['signs_en']))+sec('क्या न करें','What not to do',ul(r['dont_hi'],r['dont_en']))+sec('तुरंत क्या करें','What to do now',ul(r['do_hi'],r['do_en']))+sec('कहाँ रिपोर्ट करें','Where to report',t('हेल्पलाइन 1930 और राष्ट्रीय साइबर क्राइम रिपोर्टिंग पोर्टल।','Helpline 1930 and the National Cyber Crime Reporting Portal.'))+t('पैसे वापस मिलने की गारंटी नहीं है; नतीजा परिस्थितियों और संबंधित संस्था के नियमों पर निर्भर करता है। यह जन-जागरूकता की सामान्य जानकारी है।','Recovery of money is not guaranteed; the outcome depends on circumstances and the institution\'s rules. This is general public-awareness information.','p','m')
    else: b=sec('यह क्या है?','What is this?',w('what'))+sec('पात्रता','Eligibility',t('उपलब्ध जानकारी के आधार पर आप पात्र हो सकते हैं। अंतिम पात्रता संबंधित सरकारी प्राधिकरण तय करता है।','Based on the information available, you may be eligible. Final eligibility is determined by the relevant government authority.'))+sec('दस्तावेज़ और आवेदन','Documents and how to apply',t('सत्यापित जानकारी अभी उपलब्ध नहीं है। आवश्यकताएँ बदल सकती हैं; आधिकारिक स्रोत पर जाँचें।','Verified information is not currently available. Requirements may change; check the official source.'))+sec('सावधानी','Precautions',t('फर्जी वेबसाइट, एजेंट और पैसे माँगने वालों से बचें। OTP, PIN या पासवर्ड कभी साझा न करें।','Avoid fake websites, agents and anyone asking for money. Never share your OTP, PIN or password.'))
    if k!='scams' and 'steps_hi' in r:
        L=lambda n:ul(r[n+'_hi'],r[n+'_en']);O=lambda n:''.join(f'<ol lang="{l}">'+''.join(f'<li>{E(x)}</li>' for x in r[n+'_'+l])+'</ol>' for l in('hi','en'))
        b=sec('आपको क्या मिलेगा','What you get',w('benefit'))+sec('कौन ले सकता है','Who can apply',L('who'))+sec('ध्यान दें / कौन नहीं ले सकता','Please note / who may not qualify',L('not'))+sec('कौन से कागज़ तैयार रखें','Documents to keep ready',L('docs')+t('आवश्यकताएँ बदल सकती हैं; आधिकारिक पोर्टल पर जाँचें।','Requirements may change; check the official portal.','p','m'))+sec('आवेदन के कदम','Steps to apply',O('steps'))+sec('आम गलतियाँ','Common mistakes',L('mistakes'))+sec('ठगों से सावधान','Beware of fraud',t('OTP, PIN या पासवर्ड किसी को न बताएँ। आवेदन के लिए पैसे माँगने वाले एजेंट या फर्जी वेबसाइट से बचें। सिर्फ़ नीचे दिया आधिकारिक लिंक उपयोग करें।','Never share OTP, PIN or password. Avoid agents or fake sites asking money to apply. Use only the official link below.'))+sec('सत्यापन की स्थिति','Verification notes',L('conf'))
    b+=sec('आधिकारिक स्रोत','Official source',f'<p>{ext(r["source_url"],E(r["source_name"]))}</p>'+''.join(f'<p>{ext(u,E(n))}</p>' for u,n in r.get('more',[])))+f'<p class="m">{sp("अंतिम सत्यापन","Last verified")}: {r["last_verified"] or sp("अभी सत्यापित नहीं","not yet verified")} · v{r["version"]} · {sp("अपडेट","Updated")}: {r["updated"]}</p>'
    if r.get('last_verified') and (D(NOW)-D(r['last_verified'])).days>REVIEW_DAYS:
        REVIEW_DUE.append(f'{k}/{r["slug"]} (last verified {r["last_verified"]})')
        b=t('⚠️ इस पेज की जानकारी 6 महीने से ज़्यादा पहले जाँची गई थी। इसमें बदलाव हो सकता है — कोई कदम उठाने से पहले ऊपर दिया आधिकारिक स्रोत ज़रूर देखें।','⚠️ This page was last checked more than 6 months ago. Things may have changed — check the official source above before acting.','p','note')+b
    if r.get('valid_until'): b+=f'<p class="m">{sp("यह जानकारी इस तारीख तक मान्य","Valid until")}: {fd(r["valid_until"])}</p>'
    LASTMOD[f'/{k}/{r["slug"]}/']=r.get('updated') or SITE_UPDATED
    layout(f'/{k}/{r["slug"]}/',r['hi'],r['en'],f'<h1 lang="hi">{E(r["hi"])}</h1><h1 lang="en">{E(r["en"])}</h1><p>{badge(r["status"])}</p>'+b,r['what_en'][:150],crumbs=[(KIND[k][1],f'/{k}/')])
def idxpage(k,intro):
    rs=load(k);kh,ke=KIND[k]
    li=''.join(f'<div class="res"><a href="/{k}/{r["slug"]}/"><b>{sp(E(r["hi"]),E(r["en"]))}</b></a> {badge(r["status"])}</div>' for r in rs) or t('सत्यापित जानकारी अभी उपलब्ध नहीं है।','Verified information is not currently available.')
    if rs: page(f'/{k}/',kh,ke,intro+li,ke+' — Nagrik Saathi')
    for r in rs: rec(k,r)
    return rs
OFF=lambda u,l: f'<p>{ext(u,l)}</p>'
