IDX=[];STATEREC={}
for k,intro in[("schemes",t('यहाँ सिर्फ़ वही योजनाएँ हैं जिनका स्रोत-आधारित रिकॉर्ड मौजूद है। खाली SEO पेज नहीं बनाए जाते। अन्य योजनाओं के लिए आधिकारिक पोर्टल देखें।','Only schemes with a source-backed record are listed. No empty SEO pages are created. For other schemes see the official portal.')+OFF('https://www.myscheme.gov.in','myScheme')),("documents",t('प्रक्रिया और ज़रूरी कागज़ात राज्य के अनुसार अलग होते हैं। राज्य-विशेष प्रक्रिया तभी जोड़ी जाएगी जब आधिकारिक स्रोत जाँचा जाएगा।','Process and required papers differ by state. State-specific steps are added only after the official source is checked.')),("scams",t('ठगी के आम तरीके और बचाव। हर पेज में रिपोर्ट करने का रास्ता है।','Common scams and how to stay safe. Every page shows where to report.'))]:
    for r in idxpage(k,intro):
        IDX.append({"type":k,"hi":r['hi'],"en":r['en'],"url":f'/{k}/{r["slug"]}/',"status":r['status'],"last_verified":r['last_verified'],"scope":r['dept'],"kw":r.get('kw',''),"tags":r.get('tags',[]),"state":r.get('state','')})
        if r.get('state'): STATEREC.setdefault(r['state'],[]).append((k,r))
tiles=[("📋","योजनाएँ","Schemes","/schemes/"),("🏛️","सेवाएँ","Services","/services/"),("📄","दस्तावेज़ और प्रमाणपत्र","Documents & Certificates","/documents/"),("🔍","मेरे लिए क्या उपलब्ध है?","What's available for me?","/finder/"),("🛡️","साइबर सुरक्षा","Cyber Safety","/cyber-safety/"),("⚠️","ठगी से बचाव","Scam Safety","/scams/"),("🚨","फ्रॉड हेल्प","Fraud Help","/cyber-safety/#now"),("📞","हेल्पलाइन","Helplines","/helplines/"),("🇮🇳","केंद्र सरकार","Central Government","/central/"),("🗺️","राज्य सरकार","State Government","/states/"),("🆕","क्या नया है?","What's New?","/whats-new/"),("🔊","ऑडियो जानकारी","Audio Information","/audio/")]
