layout('/','नागरिक साथी','Nagrik Saathi','<div class="hero"><img src="/assets/img/og-banner.jpg" width="1024" height="572" alt="नागरिक साथी — आपका डिजिटल साथी। सरकारी योजनाएँ और नागरिक सेवाएँ, अब सबके लिए हुई आसान। घर बैठे पाएँ हर योजना की सही जानकारी।" fetchpriority="high"><a class="hb hb1" href="/schemes/"><span class="sr">योजनाएँ देखें — Explore Schemes</span></a><a class="hb hb2" href="/about/"><span class="sr">जुड़ें — Get Involved</span></a></div><p class="hbm"><a class="btn hbo" href="/schemes/">योजनाएँ देखें <small>(Explore Schemes)</small></a> <a class="btn hbt" href="/about/">जुड़ें <small>(Get Involved)</small></a></p>'+t('सरकारी जानकारी — आपकी भाषा में, आपकी समझ में।','Government Information — Simple, Clear & Accessible.','h1')+t('जानकारी समझें। आधिकारिक स्रोत से सत्यापित करें। सुरक्षित तरीके से आगे बढ़ें।','Understand. Verify at the official source. Proceed safely.','p','m')+t('आप क्या खोज रहे हैं?','What are you looking for?','h2')+SEARCH()+f'<div class="chips">{chips}</div>'+cards+'<div class="p">'+t('साइबर फ्रॉड हुआ है? तुरंत अपने बैंक से संपर्क करें और 1930 पर कॉल करें।','Victim of cyber fraud? Contact your bank at once and call 1930.')+f'<a class="btn primary" href="/cyber-safety/#now">{sp("अभी क्या करें","What to do now")}</a></div>'+(t('ताज़ा अपडेट','Latest updates','h2')+''.join(f'<div class="res"><small>{fd(u["date"])}</small> — '+(f'<a href="{u["url"]}">' if u.get('url') in OUT else '')+f'{sp(E(u["hi"]),E(u["en"]))}'+('</a>' if u.get('url') in OUT else '')+'</div>' for u in UPD[:3])+f'<p><a href="/whats-new/">{sp("सभी अपडेट देखें →","See all updates →")}</a></p>' if UPD else '')+f'<p class="m">{sp("साइट का अंतिम अपडेट","Site last updated")}: {fd(SITE_UPDATED)}</p>','Nagrik Saathi helps you understand government schemes, services, documents and cyber safety in simple Hindi and English, with official sources.',listen=False)
page('/search/','खोज','Search',SEARCH()+'<div id="res" aria-live="polite"></div>','Search Nagrik Saathi',noindex=True,listen=False)
cy=sec('अभी क्या करें','What to do now','<ol lang="hi"><li>तुरंत अपने बैंक या पेमेंट ऐप से संपर्क करें।</li><li>1930 पर कॉल करें और राष्ट्रीय साइबर क्राइम रिपोर्टिंग पोर्टल पर शिकायत करें।</li><li>मैसेज, स्क्रीनशॉट और लेनदेन की जानकारी डिलीट न करें।</li><li>OTP, PIN, पासवर्ड न बताएँ; अनजान को रिमोट एक्सेस न दें।</li></ol><ol lang="en"><li>Contact your bank or payment app immediately.</li><li>Call 1930 and report on the National Cyber Crime Reporting Portal.</li><li>Do not delete messages, screenshots or transaction details.</li><li>Never share OTP, PIN or password; never give strangers remote access.</li></ol>')
cy=cy.replace('<h2 lang="hi">','<h2 id="now" lang="hi">',1)+f'<p class="big">📞 1930</p><p>{ext("https://cybercrime.gov.in","cybercrime.gov.in")}</p>'+t('पैसे वापस मिलने की कोई गारंटी नहीं है। नतीजा परिस्थितियों और संबंधित संस्था के नियमों पर निर्भर करता है। उपयोग से पहले नंबर और लिंक आधिकारिक पोर्टल पर जाँचें।','Recovery of money is not guaranteed. The outcome depends on circumstances and the institution\'s rules. Confirm the number and link on the official portal before use.','p','note')+t('स्कैम लाइब्रेरी','Scam library','h2')+'<ul class="cards">'+''.join(f'<li><a href="/scams/{r["slug"]}/">{sp(E(r["hi"]),E(r["en"]))}</a></li>' for r in load('scams'))+'</ul>'
page('/cyber-safety/','साइबर सुरक्षा','Cyber Safety',cy,'What to do after cyber fraud in India: contact your bank, call 1930, report on cybercrime.gov.in, plus a library of common scams.')
hl=json.load(open('content/helplines.json',encoding='utf-8'));hb=''
for x in [h for h in hl if h['status']=='verified']:
    hb+=f'<div class="p"><b>{sp(x["h"],x["e"])}</b> {badge(x["status"])}<br>'+(f'<span class="big">{x["n"]}</span><br><small>{sp(x["a_h"],x["a_e"])} · {sp(x["g_h"],x["g_e"])} · {sp("अंतिम जाँच","Last checked")}: {x["last_verified"]} · {ext(x["src"],x["src"].split("//")[1])}</small>' if x['status']=='verified' else '<small>'+sp('नंबर नहीं दिखाया गया — आधिकारिक पुष्टि बाकी है।','Number not shown — official confirmation pending.')+'</small>')+'</div>'
page('/helplines/','सरकारी हेल्पलाइन','Government helplines',t('जिस नंबर की आधिकारिक पुष्टि नहीं हुई, उसे यहाँ नहीं दिखाया जाता।','A number without official confirmation is not shown here.')+hb,'Verified Indian government helpline numbers with source and last-checked date.')
page('/services/','सरकारी सेवाएँ','Government services',t('सेवाएँ (प्रमाणपत्र, पंजीकरण, शिकायत) योजनाओं से अलग हैं। सत्यापित रिकॉर्ड जुड़ने पर यहाँ दिखेंगे।','Services (certificates, registrations, grievances) are separate from schemes. Verified records appear here as they are added.')+f'<ul class="cards"><li></li><li><a href="/complain/">{sp("शिकायत कहाँ करें?","Where should I complain?")}</a></li><li><a href="/form-guide/">{sp("फ़ॉर्म भरने से पहले तैयारी","Before you fill a form")}</a></li><li><a href="/helplines/">{sp("हेल्पलाइन","Helplines")}</a></li></ul>'+OFF('https://www.india.gov.in','India.gov.in'),'Government services directory and official portals.')
page('/complain/','शिकायत कहाँ करें?','Where should I complain?',t('क्या हुआ? एक विकल्प चुनें।','What happened? Pick one.')+'<div id="ct" class="chips"></div><div id="ca" aria-live="polite"></div>'+t('सामान्य जानकारी, व्यक्तिगत कानूनी सलाह नहीं।','General information, not individualized legal advice.','p','m'),'Find the right complaint route for banking, cyber fraud, consumer and government service problems.')
cat=[("senior","बुजुर्ग","Senior citizen"),("student","विद्यार्थी","Student"),("farmer","किसान","Farmer"),("worker","श्रमिक","Worker"),("woman","महिला","Woman"),("disability","दिव्यांग","Person with disability"),("business","उद्यमी","Entrepreneur"),("housing","घर चाहिए","Need a house"),("unemployed","बेरोज़गार / नौकरी खोज रहे","Unemployed / job seeker"),("other","अन्य","Other")]
STATES="Andhra Pradesh,Arunachal Pradesh,Assam,Bihar,Chhattisgarh,Goa,Gujarat,Haryana,Himachal Pradesh,Jharkhand,Karnataka,Kerala,Madhya Pradesh,Maharashtra,Manipur,Meghalaya,Mizoram,Nagaland,Odisha,Punjab,Rajasthan,Sikkim,Tamil Nadu,Telangana,Tripura,Uttar Pradesh,Uttarakhand,West Bengal,Andaman and Nicobar Islands,Chandigarh,Dadra and Nagar Haveli and Daman and Diu,Delhi,Jammu and Kashmir,Ladakh,Lakshadweep,Puducherry".split(',')
page('/finder/','मेरे लिए क्या उपलब्ध है?','What is available for me?',t('सिर्फ़ मोटी जानकारी चुनें। आधार, PAN, बैंक खाता, OTP या पासवर्ड कभी न दर्ज करें।','Choose broad details only. Never enter Aadhaar, PAN, bank account, OTP or password.','p','note')+'<form id="ff"><p><label for="st">'+sp("राज्य","State")+'</label><select id="st" name="st">'+''.join(f'<option>{s}</option>' for s in STATES)+'</select></p><p><label for="ag">'+sp("आयु वर्ग","Age group")+'</label><select id="ag" name="age"><option>0-17</option><option>18-59</option><option>60+</option></select></p><p><label for="ct2">'+sp("आप कौन हैं?","Who are you?")+'</label><select id="ct2" name="cat">'+''.join(f'<option value="{v}">{h} / {e}</option>' for v,h,e in cat)+'</select></p><button class="primary" type="submit">'+sp("योजनाएँ देखें","Show schemes")+'</button></form><div id="fr" aria-live="polite"></div><p id="fn" hidden>'+t('चुनी गई जानकारी के आधार पर ये योजनाएँ प्रासंगिक हो सकती हैं। अंतिम पात्रता और आवेदन की शर्तें आधिकारिक स्रोत से सत्यापित करें। राज्य-विशेष योजनाएँ सत्यापित सामग्री जुड़ने पर दिखेंगी।','These schemes may be relevant based on the information provided. Please verify final eligibility and application requirements from the official source. State-specific schemes appear as verified content is added.','p','note')+'</p>','Simple scheme finder using only broad, non-sensitive details.')
page('/states/','राज्य सरकार','State Governments / UTs',t('राज्य-वार पेज तभी बनेंगे जब उनमें सत्यापित, उपयोगी जानकारी हो। क्षेत्रीय भाषाएँ तभी दिखेंगी जब भरोसेमंद सामग्री उपलब्ध हो।','State pages are created only when they hold verified, useful information. Regional languages appear only when reliable content exists.')+'<div class="chips">'+''.join((f'<a href="/states/{s.lower().replace(chr(32),chr(45))}/">{s} ✓</a>' if s in STATEREC else f'<span>{s}</span>') for s in STATES)+'</div>'+t('✓ वाले राज्यों में सामग्री उपलब्ध है। बाकी राज्यों की सत्यापित सामग्री अभी उपलब्ध नहीं है।','States marked ✓ have content. Verified content for the other states is not currently available.','p','note'),'State and UT structure for Nagrik Saathi.')
WN=''.join(f'<div class="p"><small><b>{fd(u["date"])}</b></small><br><b>{sp(E(u["hi"]),E(u["en"]))}</b>'+(f'<br>{sp(E(u["dhi"]),E(u["den"]))}' if u.get('dhi') else '')+(f'<br><a href="{u["url"]}">{sp("पूरी जानकारी →","Full details →")}</a>' if u.get('url') in OUT else '')+'</div>' for u in UPD)
page('/whats-new/','क्या नया है?','What\'s new?',t('नागरिक साथी पर हाल में जोड़ी या बदली गई जानकारी — सबसे नई सबसे ऊपर। पुरानी या जिसकी तारीख निकल चुकी है, वह यहाँ से अपने आप हट जाती है।','Information recently added or changed on Nagrik Saathi — newest first. Old or expired items are removed automatically.')+f'<p class="m">{sp("साइट का अंतिम अपडेट","Site last updated")}: {fd(SITE_UPDATED)}</p>'+(WN or t('अभी कोई नया अपडेट नहीं है।','No new updates right now.','p','note')),'Latest updates on Indian government schemes and services on Nagrik Saathi.')
page('/audio/','ऑडियो जानकारी','Audio information',t('हर पेज के ऊपर 🔊 सुनें बटन आपके चुने हुए भाषा में पेज पढ़ता है। यह आपके ब्राउज़र की आवाज़ का उपयोग करता है और अपने आप शुरू नहीं होता। दोबारा दबाने पर रुक जाता है।','The 🔊 Listen button at the top of each page reads it in your selected language using your browser\'s voice. It never starts by itself; press it again to stop.')+t('अगर आपके फोन में हिंदी आवाज़ नहीं है, तो सेटिंग में टेक्स्ट-टू-स्पीच के लिए हिंदी आवाज़ जोड़ें।','If your phone has no Hindi voice, add one in the text-to-speech settings.'),'Listen to Nagrik Saathi pages in Hindi or English.')
page('/how-it-works/','नागरिक साथी कैसे काम करता है','How Nagrik Saathi works',''.join(sec(h,e,t(a,b)) for h,e,a,b in[("जानकारी कौन बनाता है?","Who creates the information?","नागरिक साथी की टीम आधिकारिक स्रोतों से सरल भाषा में जानकारी तैयार करती है।","The Nagrik Saathi team prepares plain-language information from official sources."),("कौन से स्रोत?","Which sources?","पहले सीधे मंत्रालय/विभाग या आधिकारिक पोर्टल। समाचार और सोशल मीडिया सिर्फ़ संकेत हैं।","First the ministry, department or official portal directly. News and social media are only leads."),("सत्यापन कैसे?","How is it verified?","हर पेज पर स्रोत, अंतिम सत्यापन की तारीख और 🟢 स्थिति दिखती है। जो जानकारी सत्यापित नहीं हो पाती, उसे साइट पर दिखाया ही नहीं जाता।","Each page shows its source, last-verified date and a 🟢 status. Information that cannot be verified is not shown on the site."),("AI का उपयोग","How is AI used?","AI सारांश, अनुवाद, वर्गीकरण और बदलाव की तुलना में मदद कर सकता है। AI तथ्य, लिंक या नंबर नहीं गढ़ता।","AI may assist with summaries, translation, classification and comparing changes. AI never invents facts, links or numbers."),("मानव समीक्षा","Human review","पात्रता, राशि, तारीख, पेंशन या कानूनी नियम बदलने पर प्रकाशन से पहले इंसान जाँचता है।","Changes to eligibility, amounts, deadlines, pensions or legal rules are checked by a person before publishing."),("गलती सुधार","Corrections",'<a href="/report/">गलती बताएँ</a> — सुधार स्रोत से जाँचकर दर्ज होता है।','<a href="/report/">Report an error</a> — corrections are checked against the source and recorded.'),("हम क्या गारंटी नहीं देते","What we do not guarantee","मंज़ूरी, लाभ, रिफंड या किसी भी नतीजे की। जानकारी बदल सकती है।","Approval, benefits, refunds or any outcome. Information can change.")]),'How Nagrik Saathi gathers, verifies and updates information, and how AI is used.')
page('/about/','नागरिक साथी के बारे में','About Nagrik Saathi','<p class="lf"><img src="/assets/img/logo-full.png" width="800" height="296" alt="नागरिक साथी — Nagrik Saathi, Citizen\'s Digital Companion"></p>'+t('नागरिक साथी का उद्देश्य है — खोजें, समझें, सत्यापित करें, सुरक्षित आगे बढ़ें। यह स्वतंत्र मंच है और आधिकारिक स्रोतों की जगह नहीं लेता। यह अभी शुरुआती चरण में है और इसकी सीमाएँ हैं: कई पेज अभी सत्यापित नहीं हैं।','Nagrik Saathi exists to help you discover, understand, verify and proceed safely. It is independent and does not replace official sources. It is at an early stage with limits: many pages are not yet verified.')+f'<p><a href="/how-it-works/">{sp("कैसे काम करता है","How it works")}</a></p>'+f'<p>{sp("सुधार या हटाने के अनुरोध के लिए संपर्क:","For corrections or removal requests, contact:")} <a href="mailto:infinitydigital39@gmail.com">infinitydigital39@gmail.com</a></p>','About Nagrik Saathi, an independent citizen-information platform.')
page('/privacy/','गोपनीयता','Privacy',t('इस साइट पर लॉगिन नहीं है और हम नाम, फोन, आधार, PAN, बैंक या OTP नहीं माँगते। भाषा और सीनियर मोड की पसंद सिर्फ़ आपके ब्राउज़र में रहती है। होस्टिंग सेवा सामान्य तकनीकी लॉग रख सकती है। यह मसौदा है; लॉन्च से पहले DPDP अधिनियम, 2023 के अनुसार किसी योग्य पेशेवर से जँचवाएँ।','This site has no login and never asks for name, phone, Aadhaar, PAN, bank or OTP details. Your language and Senior Mode choices stay in your browser only. The hosting service may keep ordinary technical logs. This is a draft; have it reviewed by a qualified professional under the DPDP Act, 2023 before launch.'),'Nagrik Saathi privacy information.')
page('/terms/','शर्तें','Terms',t('यह साइट सामान्य जागरूकता के लिए है। हम मंज़ूरी, लाभ या रिफंड की गारंटी नहीं देते। बाहरी आधिकारिक वेबसाइटों की सामग्री के लिए वे ज़िम्मेदार हैं। यह मसौदा है और पेशेवर समीक्षा के बिना कानूनी रूप से पूर्ण नहीं माना जाए।','This site is for general awareness. We do not guarantee approval, benefits or refunds. External official websites are responsible for their own content. This is a draft and should not be treated as legally complete without professional review.'),'Nagrik Saathi terms of use.')
page('/disclaimer/','अस्वीकरण','Disclaimer',DISC+t('यह कानूनी या वित्तीय सलाह नहीं है। नियम बदल सकते हैं।','This is not legal or financial advice. Rules can change.'),'Nagrik Saathi disclaimer.')
page('/accessibility/','सुगम्यता','Accessibility',t('हम WCAG 2.1 स्तर AA के सिद्धांतों और GIGW 3.0 को मानक की तरह अपनाने का प्रयास करते हैं। अभी कोई औपचारिक ऑडिट नहीं हुआ है। सुविधाएँ: कीबोर्ड नेविगेशन, फोकस संकेत, बड़े बटन, सीनियर मोड, ऑडियो। समस्या हो तो गलती बताएँ पेज उपयोग करें।','We aim to follow WCAG 2.1 Level AA principles and use GIGW 3.0 as a benchmark. No formal audit has been done yet. Features: keyboard navigation, focus indicators, large buttons, Senior Mode, audio. If you face a problem, use the Report an Error page.'),'Nagrik Saathi accessibility statement.')
page('/report/','गलती बताएँ','Report an error',t('कोई व्यक्तिगत जानकारी न लिखें।','Do not write personal information.','p','note')+'<p><label for="rt">'+sp("समस्या","Problem")+'</label><select id="rt"><option>Outdated</option><option>Incorrect</option><option>Broken link</option><option>Translation</option><option>Missing source</option><option>Accessibility</option></select></p><p><label for="rx">'+sp("विवरण","Details")+'</label><textarea id="rx" rows="4"></textarea></p><button id="cp" class="primary" type="button">'+sp("रिपोर्ट कॉपी करें","Copy report")+'</button> <small id="cm" aria-live="polite"></small>'+t('अभी यह फ़ॉर्म भेजता नहीं है; ऑनलाइन जमा करने की सुविधा अगले चरण में जुड़ेगी।','This form does not send anything yet; online submission will be added later.','p','m'),'Report an error on Nagrik Saathi.',listen=False)
