def card(k,s):
    r=json.load(open(f'content/{k}/{s}.json',encoding='utf-8'))
    if r.get('status')!='verified': return ''
    return f'<div class="p"><a href="/{k}/{s}/"><b>{sp(E(r["hi"]),E(r["en"]))}</b></a> {badge(r["status"])}{t(E(r["what_hi"].split("।")[0]+"।"),E(r["what_en"].split(". ")[0].rstrip(".")+"."),"p","m")}</div>'
